<script setup lang="ts">
import type { VaultSource } from '~~/shared/types/sharing'
import type { ScopedCredential } from '~~/shared/utils/vault-sources'
import type { StructureView } from '~~/shared/utils/structure-relationships'
import { buildStructureMap, searchStructureGroups } from '~~/shared/utils/structure-map'
import { moneyLabel, periodLabel } from '~~/shared/utils/subscriptions'
const props=defineProps<{sources:VaultSource[];mode:StructureView}>()
const emit=defineEmits<{open:[entry:ScopedCredential];category:[key:string];vault:[id:string]}>()
const filters=useFiltersStore()
const state=computed(()=>filters.relationships.structure[props.mode])
const query=computed({get:()=>state.value.query,set:(value:string)=>{state.value.query=value}})
const linkedOnly=computed({get:()=>state.value.linkedOnly,set:(value:boolean)=>{state.value.linkedOnly=value}})
const selectedId=computed({get:()=>state.value.selectedId,set:(value:string)=>{state.value.selectedId=value}})
const overview=ref(false),resourceQuery=ref('')
const all=computed(()=>buildStructureMap(props.sources,props.mode))
const groups=computed(()=>searchStructureGroups(all.value,query.value,linkedOnly.value))
const selected=computed(()=>groups.value.find(group=>group.id===selectedId.value))
watch(groups,items=>{if(!items.some(group=>group.id===selectedId.value))selectedId.value=(items.find(group=>group.services.length+group.passwords.length+group.subscriptions.length>0)??items[0])?.id??''},{immediate:true})
const labels={category:'Категория',folder:'Папка',vault:'Хранилище'}
const icons={category:'i-lucide-folder',folder:'i-lucide-folders',vault:'i-lucide-vault'}
watch(selectedId,()=>{resourceQuery.value=''})
const lanes=computed(()=>selected.value?[
  {id:'service',label:'Сервисы',product:'Взаимосвязи',icon:'i-lucide-network',rows:selected.value.services},
  {id:'password',label:'Пароли',product:'Password',icon:'i-lucide-key-round',rows:selected.value.passwords},
  {id:'finance',label:'Подписки',product:'Финансы',icon:'i-lucide-wallet',rows:selected.value.subscriptions}
].map(lane=>({...lane,total:lane.rows.length,rows:lane.rows.filter(entry=>`${entry.title} ${entry.url} ${entry.financeSubscription?.label??''}`.toLocaleLowerCase('ru-RU').includes(resourceQuery.value.trim().toLocaleLowerCase('ru-RU')))})):[])
const vaultNames=(entry:ScopedCredential)=>(entry.vaultNames??[entry.vaultName]).join(' · ')
function choose(id:string){if(!groups.value.some(group=>group.id===id)){query.value='';linkedOnly.value=false}selectedId.value=id;overview.value=false}
function inspectChild(id:string){if(props.mode==='categories')choose(id);else{filters.relationships.structure.categories.selectedId=id;filters.relationships.structure.categories.query='';filters.relationships.structure.categories.linkedOnly=false;filters.relationships.view='categories'}}
function reset(){query.value='';linkedOnly.value=false}
</script>
<template>
  <section class="service-map structure-map" :aria-label="mode==='categories'?'Взаимосвязи категорий':'Взаимосвязи хранилищ'">
    <header class="service-map-header"><div><span class="service-map-eyebrow">СТРУКТУРА</span><h2>{{ mode==='categories'?'Категории и папки':'Хранилища' }}</h2><p>{{ mode==='categories'?'Выберите категорию или папку, чтобы увидеть её состав и связи.':'Выберите хранилище, чтобы увидеть его категории, записи и связи с другими хранилищами.' }}</p></div><div class="service-map-view" role="group" aria-label="Режим структуры"><button :aria-pressed="!overview" :class="{selected:!overview}" @click="overview=false"><UIcon name="i-lucide-panel-left"/>Состав и связи</button><button :aria-pressed="overview" :class="{selected:overview}" @click="overview=true"><UIcon name="i-lucide-layout-grid"/>Обзор</button></div></header>
    <div class="service-map-toolbar structure-map-toolbar"><UInput v-model="query" icon="i-lucide-search" placeholder="Найти группу, сервис, пароль или подписку…" aria-label="Поиск по структуре" class="service-map-search"/><UCheckbox v-model="linkedOnly" label="Только со связями"/><UButton v-if="query||linkedOnly" color="neutral" variant="ghost" label="Сбросить фильтры" @click="reset"/><span>{{ groups.length }} из {{ all.length }}</span></div>
    <div v-if="!groups.length" class="service-map-empty"><UIcon :name="mode==='categories'?'i-lucide-folders':'i-lucide-vault'"/><h3>{{ query||linkedOnly?'Группы не найдены':'Здесь пока нет групп' }}</h3><p>{{ query||linkedOnly?'Измените поиск или отключите фильтр связей.':'Категории, папки и хранилища появятся после их создания.' }}</p><UButton v-if="query||linkedOnly" color="neutral" variant="outline" label="Сбросить фильтры" @click="reset"/></div>
    <div v-else-if="overview" class="service-map-overview" aria-label="Обзор структуры"><button v-for="group in groups" :key="group.id" class="service-overview-card" :aria-label="`Показать состав: ${labels[group.kind]} ${group.label} · ${group.subtitle}`" @click="choose(group.id)"><div><span class="service-map-avatar"><UIcon :name="icons[group.kind]"/></span><strong>{{ group.label }}</strong><UIcon name="i-lucide-arrow-up-right"/></div><small>{{ labels[group.kind] }} · {{ group.subtitle }}</small><div class="service-overview-counts"><span><UIcon name="i-lucide-network"/>Сервисы: {{ group.services.length }}</span><span><UIcon name="i-lucide-key-round"/>Пароли: {{ group.passwords.length }}</span><span><UIcon name="i-lucide-wallet"/>Подписки: {{ group.subscriptions.length }}</span></div><p>{{ group.connections.length }} связанных групп<template v-if="group.children.length"> · {{ group.children.length }} вложенных групп</template></p></button></div>
    <div v-else-if="selected" class="service-map-layout">
      <aside class="service-map-catalog" aria-label="Группы структуры"><h3>{{ mode==='categories'?'Категории и папки':'Хранилища' }}<span>{{ groups.length }}</span></h3><div class="service-map-service-list"><button v-for="group in groups" :key="group.id" :aria-label="`Показать состав: ${labels[group.kind]} ${group.label} · ${group.subtitle}`" :aria-pressed="group.id===selectedId" :class="{selected:group.id===selectedId}" @click="choose(group.id)"><span class="service-catalog-name"><UIcon :name="icons[group.kind]"/>{{ group.label }}</span><small>{{ labels[group.kind] }} · {{ group.subtitle }}</small><span class="service-catalog-counts"><span><UIcon name="i-lucide-network"/>{{ group.services.length }}</span><span><UIcon name="i-lucide-key-round"/>{{ group.passwords.length }}</span><span><UIcon name="i-lucide-wallet"/>{{ group.subscriptions.length }}</span></span></button></div></aside>
      <div class="service-map-stage" aria-label="Состав выбранной группы" aria-live="polite"><div class="service-map-anchor"><div class="service-map-anchor-main"><span class="service-map-avatar"><UIcon :name="icons[selected.kind]"/></span><div><span class="service-map-eyebrow">{{ labels[selected.kind] }}</span><h3>{{ selected.label }}</h3><p>{{ selected.subtitle }}</p></div></div><UButton v-if="selected.kind==='vault'" color="neutral" variant="outline" icon="i-lucide-filter" label="Выбрать хранилище" @click="emit('vault',selected.vaultId)"/><UButton v-else-if="selected.categoryKey&&!/^подписк[аи]$/i.test(selected.label.trim())" color="neutral" variant="outline" icon="i-lucide-arrow-up-right" label="Открыть в Password" @click="emit('category',selected.categoryKey)"/></div>
        <section v-if="selected.children.length" class="structure-map-children" aria-label="Вложенные группы"><h3>{{ selected.kind==='folder'?'Категории в папке':'Категории и папки' }}</h3><div><button v-for="child in selected.children" :key="child.id" :aria-label="`Открыть группу: ${child.label} · ${child.subtitle}`" @click="inspectChild(child.id)"><UIcon :name="icons[child.kind]"/><span>{{ child.label }}</span><small>{{ labels[child.kind] }} · {{ child.subtitle }}</small><UIcon name="i-lucide-arrow-right"/></button></div></section>
        <UInput v-model="resourceQuery" class="structure-map-resource-search" icon="i-lucide-search" placeholder="Найти запись в выбранной группе…" aria-label="Поиск записей в группе"/><p class="service-map-explanation">Записи выбранной группы · общая запись учитывается один раз</p><div class="service-map-lanes"><section v-for="lane in lanes" :key="lane.id" :class="['service-map-lane',lane.id]" :aria-label="`${lane.label} группы ${selected.label}`"><div class="service-lane-heading"><span><UIcon :name="lane.icon"/>{{ lane.label }}</span><strong>{{ lane.rows.length }}<template v-if="resourceQuery"> / {{ lane.total }}</template></strong></div><p class="service-lane-product">{{ lane.product }}</p><div v-if="!lane.rows.length" class="service-lane-empty">{{ resourceQuery?'Совпадений нет.':'Записей нет.' }}</div><article v-for="entry in lane.rows" :key="entry.sharedCardId||`${entry.vaultId}/${entry.id}`" class="service-resource"><button :aria-label="`Открыть запись: ${entry.title}${entry.financeSubscription?' · '+entry.financeSubscription.label:''}`" @click="emit('open',entry)"><strong>{{ entry.title }}</strong><UIcon name="i-lucide-arrow-up-right"/><span v-if="entry.financeSubscription&&entry.financeSubscription.label!==entry.title">{{ entry.financeSubscription.label }}</span><small>{{ vaultNames(entry) }}</small></button><p v-if="entry.financeSubscription?.subscription" class="service-resource-price">{{ moneyLabel(entry.financeSubscription.subscription) }} / {{ periodLabel(entry.financeSubscription.subscription) }}</p></article></section></div>
        <section class="structure-map-connections" aria-label="Связанные группы"><div><h3>Связи с другими {{ mode==='categories'?'категориями и папками':'хранилищами' }}</h3><span>{{ selected.connections.length }}</span></div><p v-if="!selected.connections.length">Связей с другими группами нет.</p><article v-for="connection in selected.connections" :key="connection.id"><button :aria-label="`Перейти к группе: ${connection.label} · ${connection.subtitle}`" @click="choose(connection.id)"><span class="service-map-avatar"><UIcon :name="icons[connection.kind]"/></span><span><strong>{{ connection.label }}</strong><small>{{ labels[connection.kind] }} · {{ connection.subtitle }}</small></span><UIcon name="i-lucide-arrow-right"/></button><div class="structure-connection-tags"><span v-if="connection.shared">Общих записей: {{ connection.shared }}</span><span v-if="connection.kinds.includes('manual')">Привязки между записями</span><span v-if="connection.kinds.includes('folder')">Категории в папках</span></div><details><summary>Пояснения · {{ connection.reasons.length }}</summary><p v-for="reason in connection.reasons" :key="reason">{{ reason }}</p></details></article></section>
      </div>
    </div>
  </section>
</template>
